function columnTops(c) {
  const d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data, tops = new Int16Array(c.width);
  for (let x = 0; x < c.width; x++) {
    let y = 0;
    while (y < SHIP_WL_ROW && !d[(y * c.width + x) * 4 + 3]) y++;
    tops[x] = y;
  }
  return tops;
}

// Sea life is drawn as dark silhouettes, at a scale that suits the battleships.
const FISH_DEFS = {
  sardine: { px: 0.75, rows: ['t.bbbb..', 'ttbbbbbb', 't.bbbb..'] },
  tang: { px: 0.85, rows: ['...yy...', 'y.yyyyy.', 'yyyyyyyy', 'y.yyyyy.', '...yy...'] },
  clown: { px: 0.8, rows: ['..oooo..', 't.oooooo', 't.oooooo', '..oooo..'] },
  blue: { px: 0.85, rows: ['..bbbb...', 'tbbbbbbb.', 'tbbbbbbbb', '..bbbb...'] },
  snapper: { px: 0.9, rows: ['....rrr...', 't..rrrrrr.', 'trrrrrrrrr', 't..rrrrrr.', '....r.....'] },
  angel: { px: 0.8, rows: ['...k..', '..kkk.', '.kkkkk', 'tkkkkk', '.kkkkk', '..kkk.', '...k..'] },
};
const SEA_INK = '#06101c';
const deadFish = [];
// a blast in the water stuns the fish around it: they're thrown outward, then float up belly first
// (Nov 1: the schools and their fish are column tables - 05-game-state.js; each school's fish from last to first, as before)
function killFishNear(x, y, r) {
  const S = schools.c, F = seaFish.c, FI = schoolFish();
  for (let si = 0; si < schools.n; si++) {
    if (Math.abs(S.x[si] - x) > r + 60 || Math.abs(S.y[si] - y) > r + 60) continue;
    for (let q = FI.at[si + 1] - 1; q >= FI.at[si]; q--) {
      const j = FI.rows[q], fx = F.x[j], fy = F.y[j], d = Math.hypot(fx - x, fy - y);
      if (d > r) continue;
      seaFish.drop(j);
      if (deadFish.length > 120) deadFish.shift();
      const push = (1 - d / r) * 160 + 30, ux = (fx - x) / (d || 1), uy = (fy - y) / (d || 1);
      deadFish.push({ type: schools.str(S.type[si]), dir: F.face[j] || S.dir[si], x: fx, y: fy, vx: ux * push, vy: uy * push, rot: 0, w: seaRnd(-8, 8), t: 0, fade: 1, surf: false });
    }
  }
  seaFish.sweep();
  killBigNear(x, y, r * 0.4);                                     // (the sharks and whales in it killed too, user Oct 29 - 35-zz-sea-kills.js)
  for (const sh of sharks) if (Math.hypot(sh.x - x, sh.y - y) < r * 1.5 && !sh.turn) sh.dir = sh.x < x ? -1 : 1;   // the others turn away
}
function stepDeadFish(dt) {
  stepSeaKills(dt);                        // (dead sharks and whales, their blood: 35-zz-sea-kills.js)
  for (let i = deadFish.length - 1; i >= 0; i--) {
    const f = deadFish[i];
    f.t += dt;
    f.vx *= 1 - 2.5 * dt; if (f.t < 0.5) f.vy *= 1 - 2.5 * dt; f.w *= 1 - 1.5 * dt;
    const sy = surfaceY(f.x);
    if (!f.surf) {
      if (f.t > 0.5) f.vy += (-24 - f.vy) * 0.9 * dt;              // once the blast's push dies, they float up belly first
      f.rot += (f.w + (0 - f.rot) * 0.8) * dt;
      f.x += f.vx * dt; f.y += f.vy * dt;
      if (f.y <= sy + 1.5) { f.surf = true; f.y = sy + 1.5; }
    } else {
      // floating on the surface, rocked by the swell, drifting with the wind, slowly fading
      f.y = sy + 1.5; f.x += (E.windU || 0) * 0.04 * dt; f.rot = Math.atan2(surfaceY(f.x + 3) - surfaceY(f.x - 3), 6);
      if (f.t > 40) f.fade -= dt / 8;
    }
    if (f.fade <= 0) deadFish.splice(i, 1);
  }
}
