function textWidthC(str, sc = 1, k = sc) { const P = String(str).split('$'); let w = 0; P.forEach((t, i) => { if (i) w += 7 * k + (t || i < P.length - 1 ? sc : 0); if (t) w += textWidth(t) * sc + (i < P.length - 1 ? sc : 0); }); return w; }
