function drawTextC(c, str, x, y, col, sc = 1, align = 'left', ink = null, k = sc) {
  str = String(str); if (str.indexOf('$') < 0) { if (ink) drawText(c, str, x + 1, y + 1, ink, sc, align); return drawText(c, str, x, y, col, sc, align); }
  const W = textWidthC(str, sc, k), P = str.split('$'); let X = Math.round(align === 'center' ? x - W / 2 : align === 'right' ? x - W : x);
  const cy = Math.round(y + (5 * sc - 7 * k) / 2);
  P.forEach((t, i) => {
    if (i) { drawCoin(c, X, cy, k); X += 7 * k + (t || i < P.length - 1 ? sc : 0); }
    if (t) { if (ink) drawText(c, t, X + 1, y + 1, ink, sc); X += drawText(c, t, X, y, col, sc) + (i < P.length - 1 ? sc : 0); }
  });
  return W;
}
function drawText(c, str, x, y, col, scale = 1, align = 'left') {
  str = trText(str);
  const key = str + '|' + col + '|' + scale;
  let t = textCache.get(key);
  if (!t) {
    const base = textCanvas(str, Array.isArray(col) ? col : rgb(col));   // (a colour as '#rrggbb' or [r, g, b] - the editors pass [r, g, b]; read as hex it was black: every editor label, Nov 8)
    t = scale === 1 ? base : makeCanvas(base.width * scale, base.height * scale);
    if (scale !== 1) { const g2 = t.getContext('2d'); g2.imageSmoothingEnabled = false; g2.drawImage(base, 0, 0, t.width, t.height); }
    textCache.set(key, t); t._tk = key;
    picKeep(t, 'words', textGone);                     // (in the page's picture memory - 04-zzz-pics.js; was the last 300 kept)
  }
  picUse(t);
  const ox = align === 'center' ? Math.round(t.width / 2) : align === 'right' ? t.width : 0;
  c.drawImage(t, Math.round(x) - ox, Math.round(y) - (t.__top || 0) * scale);   // (an accented line: its marks above the letters' row)
  return t.width;
}

