/* ---------------- The drive order (the engine-room telegraph): left / stop / right, as a notch 0..6 ---------------- */
const telegraphs = [0, 1].map(player => ({ player, idx: 3, cx: 0 }));   // cx: where its sounds come from (the player's half)
// the UI sounds of each player's controls come from the middle of that player's half of the screen
function layoutControls() {
  for (const p of [0, 1]) telegraphs[p].cx = gunCtl[p].cx = ONEVIEW() ? ubw / 2 : (p + 0.5) * ubw / 2;
}

function setOrder(t, idx) {
  idx = clamp(idx, 0, 6);
  if (idx !== t.idx) sound('clink', t);
  t.idx = idx;
  // the order goes to the boat you're in (a boat you left keeps the last one you gave her)
  const m = crew[t.player] && crew[t.player].mode;
  if (m === 'ship' && ships[t.player]) ships[t.player].input = NOTCH_VAL[idx];
  if (m === 'sub' && subs[t.player]) subs[t.player].input = NOTCH_VAL[idx];
  if (m === 'tank' && tanks[t.player]) tanks[t.player].input = NOTCH_VAL[idx];
  if (m === 'heli' && helis[t.player]) helis[t.player].input = NOTCH_VAL[idx];
  if (m === 'civ' && crew[t.player].civ) crew[t.player].civ.cin = NOTCH_VAL[idx];
}
// (less where the stage sits on the page: fitted to the visible viewport, it can start below the page's top)
let STAGE_X = 0, STAGE_Y = 0;
const toUI = (clientX, clientY) => [(clientX - STAGE_X) * dpr / PIXU, (clientY - STAGE_Y) * dpr / PIXU];
function nearSink(sh) {
  // one more hit would finish her: a section on its second hit, or four hits in all
  let sum = 0;
  for (const v of sh.lvl) { if (Math.ceil(v - 1e-6) >= 2) return true; sum += Math.ceil(v - 1e-6); }
  return sum >= MAX_HITS;
}

/* ---------------- Aiming and firing: the gun you're on (the ship's turrets, or the tower's), the holds ---------------- */
const gunCtl = [0, 1].map(player => ({ player, cx: 0 }));   // (cx: where its sounds come from)
const holding = [null, null];
const mgHold = [false, false];       // the battleship's / tower's machine gun held down   // fire button held: { t }

function controlling(p) { return crew[p].mode; }
// The harbour runs itself: a boat you take out is brought through her gate and out past the end of the pier,
// where she stops and is yours; a boat sent home sails back to the pier's end and is taken in through her gate.
// You only steer out on the open water.
function vehicleOf(p) { const m = crew[p].mode; return m === 'ship' ? ships[p] : m === 'sub' ? subs[p] : null; }
function stepAutopilot(p) {
  const v = vehicleOf(p), t = telegraphs[p];
  if (!v || (v === ships[p] ? v.state !== 'afloat' : v.state !== 'out')) return;
  // the harbour has her (or she's sailing home by herself): the lever shows the way she's going, without
  // changing her own order
  if ((v.gate || v.auto === 'home') && v.dock) { const s = v.gate === 'out' ? -v.dock.dir : v.dock.dir, n = s < 0 ? 0 : 6; if (t.idx !== n) t.idx = n; }
}
// the way out of a harbour, as a lever notch: toward the sea
const outNotch = d => -d.dir > 0 ? 6 : 0;
// The player's own order to the boat they're in. It's always obeyed, even while the harbour has her: pointed out
// to sea while she's being taken in (or sailing home), she turns straight back out; pointed home while she's
// being brought out, she goes back in.
function driveCmd(p, idx) {
  const t = telegraphs[p], v = vehicleOf(p);
  setOrder(t, idx);
  if (!v || !v.dock) return;
  const d = v.dock, dir = Math.sign(NOTCH_VAL[idx]);
  if (v.gate === 'in' && dir === -d.dir) launchOut(v);
  else if (v.gate === 'out' && dir === d.dir) bringIn(v);
  else if (v.auto === 'home' && dir !== d.dir) v.auto = null;
}
/* Hold to drive (user Oct 31, the Story spec: "All vehicle acceleration uses press-and-hold input rather than a toggle. To
   stop, release the forward control. Planes keep moving forward"; "Remove the Stop button"): one rule for every vehicle and
   every input - the touch buttons, the keys, the pad's stick. Held: full ahead that way (it turns round); let go: it stops.
   A plane only turns round on a push and flies on when let go. The minisub was already held (msHold). */
// what pushing left (-1) or right (1) does in what p is in
function drivePush(p, d) {
  const c = crew[p], m = c.mode;
  if (msOf(p)) { msHold[p] = d; return; }
  if (m === 'civ' && c.civ && civLever(c.civ)) { act(p, 'planeDir', d); return; }   // (a civilian boat, ship, balloon, helicopter, sub: its lever)
  if (m === 'plane' || m === 'civ') { act(p, 'planeDir', d); return; }           // (anything flying as a plane: it turns round)
  if (m === 'ship' || m === 'sub' || m === 'tank' || m === 'heli') act(p, 'drive', d < 0 ? 0 : 6);
}
// let go: whatever drives on its own power stops; a plane flies on
function driveRelease(p) {
  const c = crew[p], m = c.mode;
  if (msOf(p)) { msHold[p] = 0; return; }
  if (m === 'civ' && c.civ && civLever(c.civ)) { act(p, 'planeDir', 0); return; }
  // (Oct 31: sent whatever the page's telegraph says - with the simulation worker the page's telegraph isn't the game's, it
  // read 'stopped' and nothing was sent: a ship let go of sailed on. A release is an edge: once, not every frame)
  if (m === 'ship' || m === 'sub' || m === 'tank' || m === 'heli') act(p, 'drive', 3);
}
// STOP, a plane's only (user Oct 31: "bring back the stop button just for planes so it can stay hovering" - the button,
// R / ] and the left stick pressed in, as before Version 384): it circles on the spot (loiterBack); on the ground it stops rolling
const flyingPlane = p => crew[p].mode === 'plane' || (crew[p].mode === 'civ' && civPlane(crew[p].civ));
function stopPlane(p) { if (flyingPlane(p)) act(p, 'planeDir', 0); }
// pressing the button of a vehicle that's on its way home: it turns round and goes back out at once
function comeBackOut(p, k) {
  const t = telegraphs[p];
  if (k === 'plane') {
    const pl = planes[p], homeF = SIDE(p) ? 1 : -1;
    if (pl && pl.state === 'fly' && pl.auto === 'home') { pl.auto = null; if (pl.facing === homeF && !pl.turn) planeTurn(pl); return true; }
    return false;
  }
  const v = k === 'ship' ? ships[p] : k === 'sub' ? subs[p] : null;
  if (!v || !v.dock) return false;
  const d = v.dock;
  if (v.gate === 'in') { launchOut(v); setOrder(t, 3); return true; }
  if (v.auto === 'home' || (!v.gate && Math.sign(v.input || 0) === d.dir)) { v.auto = null; v.input = NOTCH_VAL[outNotch(d)]; if (crew[p].mode === k) setOrder(t, outNotch(d)); return true; }
  return false;
}
// The tower gun may depress below horizontal, but only as far as its shells still clear its own quay
function elevMin(p) {
  if (lampOf(p)) return 0;                                     // (the minisub's light: right round below it, never up - user Oct 27)
  if (controlling(p) === 'heli') return -80;                 // (LAND TEST: the helicopter's nose gun, well down)
  if (controlling(p) === 'civ') return -80;                  // (the fire helicopter's water cannon)
  if (controlling(p) === 'tank') return -6;
  if (controlling(p) !== 'tower') return ELEV_MIN;
  return -15;                             // (user Oct 25: down to 15 below, for subs close to the dock; your own pier your rounds pass)
}
const gunOf = sh => sh.gun || guns[sh.id];      // (a STORY raider carries its own gun)
function activeGun(p) { const m = controlling(p); { const L = lhLampOf(p); if (L) return L; } if (m === 'civ' && civHelis.includes(crew[p].civ)) return hoseGun(crew[p].civ); if (m === 'civ' && msOf(p)) return msOf(p).lamp; if (m === 'sub' && subLampOf(p)) return subLampOf(p); return m === 'heli' ? hguns[p] : m === 'ship' || m === 'tank' ? guns[p] : tguns[p]; }


// what you're in has an ANGLE / POWER (activeGun) that the keys, the right stick, the guest's link aim - one path
// for every one (user Oct 27: "The controls should be UNIVERSAL. Like the normal helicopter."); the minisub's light
// is pointed on its own (msOf, below its hull)
function hasGuns(p) { const m = crew[p].mode; return m === 'ship' || m === 'tower' || m === 'tank' || m === 'heli' || (m === 'civ' && isFireHeli(crew[p].civ)); }
// a helicopter's gun (the army one's nose gun, the fire one's water cannon): up / down fly it, so the power keys
// tilt the gun instead
const heliAim = p => crew[p].mode === 'heli' || (crew[p].mode === 'civ' && isFireHeli(crew[p].civ));
function pressFire(p, k) {
  const m = controlling(p);
  if (m === 'civ') { civLaunch(p); return; }   // (OPEN WORLD: the research ship's fire button lets her sub down)
  sound('click', gunCtl[p]);
  if (m === 'tower') fireTower(myTw(p), false); else if (m === 'ship') fireGun(ships[p], k);
  else if (m === 'tank') tankFire(tanks[p]); else if (m === 'heli') { heliRocket(helis[p]); return; } else return;
  holding[p] = { t: 0 };
}
function releaseFire(p) { holding[p] = null; }
function updateHolds(dt) {
  for (const g of guns) if (g && g.safeT > 0) g.safeT -= dt;
  for (let p = 0; p < 2; p++) holdsFor(p, dt);
  for (const st of NET.seats) viaSeat(st, q => holdsFor(q, dt));     // (teammates: their own triggers)
}
function holdsFor(p, dt) {
  {
    // the battleship's and the tower's machine guns: held, they fire on and on
    const m = controlling(p);
    if (mgHold[p] && (m === 'ship' || m === 'tower' || m === 'tank') && (!ui.menu || NET.remote)) {
      const g = m === 'ship' || m === 'tank' ? guns[p] : tguns[p];
      g.mgT = (g.mgT || 0) - dt;
      // (the tower's guns fire half as many rounds again, user Oct 25: they should feel powerful)
      while (g.mgT <= 0) { g.mgT += m === 'tower' ? VTUNE.mg.rate / 1.5 : m === 'ship' ? VTUNE.mg.shipRate : VTUNE.mg.rate; if (m === 'ship') shipMG(ships[p]); else if (m === 'tank') tankMG(tanks[p]); else { fireTower(myTw(p), true); firePierGun(myTw(p)); /* (its second gun wherever it is: its harbour's pier or its own top - Nov 1) */ } }
    } else { if ((m === 'ship' || m === 'tank') && guns[p]) guns[p].mgT = 0; if (m === 'tower' && tguns[p]) tguns[p].mgT = 0; if (m !== 'ship' && m !== 'tower' && m !== 'tank' && m !== 'heli' && !(m === 'civ' && isFireHeli(crew[p].civ))) mgHold[p] = false; }   // (the fire helicopter's water is held too)
    const h = holding[p];
    if (!h) return;
    h.t += dt;
    if (true || controlling(p) !== 'tower' || h.t < MG_HOLD) return;        // (the tower's machine gun is gone: it fires shells)
  }
}

function unitFacing(p) { const m = crew[p].mode; return m === 'tower' ? myTw(p).facing : m === 'tank' && tanks[p] ? tanks[p].facing : m === 'heli' && helis[p] ? helis[p].facing : ships[p].facing; }
// the battleship's turrets swing right round (up to 180 degrees, firing astern); the tower's gun to straight up
function elevMax(p) { const m = crew[p].mode; if (lampOf(p)) return 180; return m === 'ship' || m === 'tank' || m === 'tower' ? 180 : m === 'heli' ? 25 : m === 'civ' ? 35 : ELEV_MAX; }   // (the tower right round too, user Oct 25: planes going the other way)
const SUB_TURN = 140;                                        // world units of depth per turn of the (keyboard) dive wheel
// the keyboard's dive keys turn an imaginary wheel: the sub's target depth follows
function turnWheel(p, degs) {
  if (crew[p].mode !== 'sub') return;
  const sb = subs[p];
  sb.depthT = clamp(sb.depthT + degs / 360 * SUB_TURN, waterLv(sb.x), subMaxY(sb.x, sb.y));   // (from her own water's surface - waterLv: every water as the ocean, user Nov 3)
}

/* ================================================================
   Periscope zoom: five brass sections. Pull it out to look closer.
   ================================================================ */
// THE STEPPED ZOOM (user Oct 27 evening: "when we zoom in/out it slows down a lot... maybe the zoom could happen in a cut
// vs the camera zooming out smoothly? It also looks not that great since its pixel art"). The zoom goes in cuts between
// fixed levels, no easing through the zooms between: every sprite was rebuilt at each in-between scale, every cloud
// re-placed, and pixel art at a fractional scale shimmers. The levels respect the pixel ratio: each is a zoom at which
// one screen pixel is a whole number N of the ship art's pixels (SHIP_K * S * z = 1 / N), so the art lands on the
// pixel grid at every level. They depend on the screen (S): setZoomLevels, at every resize.
let ZOOM_LEVELS = [0.35, 0.42, 0.5, 0.6, 0.72, 0.85, 1.08, 1.32, 1.72, 2.25];   // (until the screen is known)
// (user Nov 1 23:01: "I dont seem to be able to zoom more than this ... when driving a car? i would expect at least one more zoom
// level") ZOOM_TOP no longer stops short of the closest level: the closest is one screen pixel to one art pixel (ZOOM_NS's 1), on any
// screen (it was 2.25 - on a big screen that level fell just past it)
const ZOOM_REF = 1.32, ZOOM_TOP = 24;   // (user Nov 3 22:07, the Vegetation Lab: "I should be able to zoom in 4x more at least" - was 6)   // (ZOOM_REF: what the sky and the distance are drawn for; ZOOM_TOP, ZOOM_MIN: the bounds)
let ZN = ZOOM_LEVELS.length;
const zoomLevelOf = z => { let best = 1; for (let k = 1; k <= ZN; k++) if (Math.abs(ZOOM_LEVELS[k - 1] - z) < Math.abs(ZOOM_LEVELS[best - 1] - z)) best = k; return best; };
const ZOOM_NS = [0.25, 1 / 3, 0.5, 1, 2, 3, 4, 5, 6, 7, 8, 10, 12, 14, 16, 20, 24, 28, 32, 40, 48, 64, 80, 96, 128];   // (the art pixels a screen pixel: every step near, wider apart far out; past 32 the Oct 27 night levels, 4x further out)
function setZoomLevels() {
  const k = GRID_K * S, lv = [];   // (the old battleship art's pixel: real scale left the levels as they were)
  for (const N of ZOOM_NS) { const z = 1 / (N * k); if (z <= ZOOM_TOP * 1.001 && z >= ZOOM_MIN * 0.999) lv.push(+z.toFixed(4)); }
  lv.sort((a, b) => a - b);
  if (lv.length < 2) return;
  ZOOM_LEVELS = lv; ZN = lv.length;
  for (const p of [0, 1]) { const q = scopes[p]; q.level = clamp(zoomLevelOf(cam.zt[p] || ZOOM_START), 1, ZN); q.shown = q.level; if (!zoomLocked(p)) cam.zt[p] = ZOOM_LEVELS[q.level - 1]; }
}
const scopes = [0, 1].map(player => ({ player, cx: 0, base: 0, level: zoomLevelOf(ZOOM_START), shown: zoomLevelOf(ZOOM_START) }));
function scopeZoom(p) {
  const lv = scopes[p].level;
  return ZOOM_LEVELS[lv - 1];
}
function setScope(p, lv) { if (NET.remote) return; scopes[p].level = clamp(lv, 1, ZN); cam.zt[p] = scopeZoom(p); }
// (Oct 24 night each vehicle remembered its own zoom; user Oct 27: "When you turn on any vehicle it should not be
// zooming in or out. It's ok to pan." - the zoom is the player's, kept across switches)

/* ================================================================
   Run slider: once you step off the ship at the dock, the speed
   lever turns into a slider for your sailor. Let go and he stops.
   ================================================================ */
const runCtl = [0, 1].map(player => ({ player, cx: 0, cy: 0, w: 100, v: 0, drag: false }));
