    if (h && (h.state === 'fly' || h.state === 'landed')) { const x = mx(h.x), hy = Math.min(y - 3, y - 1 - alt(h.y + 60)); ug.fillRect(x - 3, hy, 7, 2); ug.fillRect(x - 5, hy - 2, 11, 1); }
