  water: p => { if (crew[p].mode === 'civ') hoseToggle(crew[p].civ); },   // (the fire helicopter's water cannon, user Oct 27)
  sails: p => toggleSails(yachtFor(p)),          // (a yacht: set or furl her sails, user Oct 26)
  cw: (p, wk) => civWeapon(p, wk),               // (user Oct 27: a vehicle's own green button - anchor, horn, fireworks, magnet, sails, ping, smoke, satellite)
  ping: p => minisubPing(p),                     // (the minisub: a wave toward her ship, user Oct 27)
  launch: p => civLaunch(p),                     // (OPEN WORLD: the research ship lets her sub down)                // (LAND TEST: the helicopter's magnet, user Oct 25)
  rocket: p => crew[p].mode === 'heli' ? heliRocket(helis[p]) : fireRocket(planes[p]),
  torp: p => fireTorpedo(subs[p], false),          // (the vertical torpedo is gone: user Oct 29)
  light: p => toggleLight(p),                      // (the army sub's light, user Oct 29; every helicopter's, user Oct 31)
  mine: p => layMine(subs[p]),
  smoke: p => crew[p].mode === 'tank' ? tankScreen(tanks[p]) : dropSmoke(ships[p]),   // (the tank's too: user Oct 25)
  // the plane: -1 / 1 head left / right, 0 circle on the spot
  planeDir: (p, d) => {
    if (crew[p].mode === 'civ') { civDir(p, d); return; }   // (OPEN WORLD: a civilian vehicle)
    const pl = planes[p]; if (!pl) return;
    if (pl.state === 'fly' && pl.ground) { planeGroundCmd(pl, d); return; }   // (OPEN WORLD: on the runway)
    pl.auto = null;
    if (!d) { if (pl.state === 'fly') pl.loiter = { x: pl.x }; return; }
    pl.loiter = null;
    const now = pl.turn ? -pl.turn.from : pl.facing;
    if (d !== now && !pl.turn) planeTurn(pl);
  },
