  if (held.has('ArrowLeft')) ax -= 1; if (held.has('ArrowRight')) ax += 1; if (held.has('ArrowUp')) ay -= 1; if (held.has('ArrowDown')) ay += 1;
  if (held.has('Equal') || held.has('NumpadAdd')) zf += 1; if (held.has('Minus') || held.has('NumpadSubtract')) zf -= 1;
