// (engine stage 3) the battleships' own random source (their physics here, sinking and the pieces in 34-splashes-sinking),
// made on first use: this file is read before the tables (36-zz-tables); their tables in 36-zz-vehicles.js
let vehShipR_ = null;
function vehShipR() { return (vehShipR_ || (vehShipR_ = sysRng('vehShips')))(); }
