    for (let n = 0; n < 4; n++) water.push(sh.x + vehShipRnd(-0.5, 0.5) * SHIP_L - dir * vehShipRnd(0, 0.35) * SHIP_L, (vehShipR() - 0.5) * CHURN_K * sp);
