    if (A.n === 2 && A.r[1][0] <= A.r[0][1] && A.r[0][0] <= A.r[1][1]) { A.r[0][0] = Math.min(A.r[0][0], A.r[1][0]); A.r[0][1] = Math.max(A.r[0][1], A.r[1][1]); A.n = 1; }
    for (const [a, b] of wetRuns) for (let k = 0; k < A.n; k++) { const lo = Math.max(a, A.r[k][0]), hi = Math.min(b, A.r[k][1]); if (hi > lo + 2) stepWaterRun(dt, clearForces, lo, hi); }
