function sfxMissile(x) {   // (the warplane's missile: renamed from sfxRocket, Oct 27 - the shuttle's rumble had the same name and won)
  if (!SFX.ctx) return;
  const out = sfxOut(x, 0.55); if (!out) return;
  const t = SFX.ctx.currentTime;
  // the ignition's crack, then the motor's tearing hiss falling away
  noiseShot(out, t, 0.04, 'bandpass', 3000, 1600, 2, 0.45, 0.001);
  noiseShot(out, t + 0.01, 0.9, 'highpass', 2600, 900, 0.8, 0.3, 0.02);
  thump(out, t, 160, 70, 0.1, 0.3);
}
function dropBomb(pl) {
  if (!pl || pl.state !== 'fly') return;
  if (pl.bombs <= 0 || pl.bk > 0 || planeFrozen(pl)) { sound('empty', pl.x); return; }
  pl.bombs--; pl.bk = VTUNE.plane.bombReload;
  // it falls away carrying the plane's whole momentum, then only gravity and the air act on it
  sound('bombDrop', pl.x);
  // (user Oct 25: it leaves at the plane's angle - climbing, it points up - and then its heavy nose drops)
  const b = { x: pl.x + pl.facing * 2, y: pl.y + 9, vx: pl.vx, vy: pl.vy, owner: pl.id, by: uidOf(pl), from: 'bomb', age: 0, trail: 0, under: false, ut: 0, face: pl.facing, a: Math.atan2(pl.vy, pl.vx || pl.facing) };
  shells.push(b);
  sound('whoosh', b);                                     // (its whistle: rising as it gathers speed, heard near it)
}

/* ================================================================
   ONE FLIGHT MODEL FOR EVERY FIXED-WING PLANE (user Nov 2 16:09-16:16: "if you gain speed when you're diving and you raise the
   plane up, you'd be able to do a loop on a Cessna or an army plane"; "landing to feel more realistic and meaty. Right now it
   feels very rigid"). The warplane, a Cessna or a 747, the seaplane: each calls flyStep with its own make (FLIGHT) - never a
   flight of its own (rules section 6: one rule for everything).
   The model (point mass along its path, as in the references the user sent: Marco Monster's car paper's sister - the textbook
   flight-path equations -, leopnt/plane-model-2d-godot (stable because lift acts behind its weight: the nose keeps turning
   into its air), Flightle (pitch trades height for speed, a trim it returns to, the stall, the flare)):
   - its path: speed V along it at gam (the path's angle from its facing, + down - as pitch always was), turned by lift
     (toward its canopy) against gravity: dgam/dt = (g cos gam - L) / V; dV/dt = T cos a - D + g sin gam;
   - its wings: lift L = KL V^2 CL(a), CL rising with the angle of attack a to 1 at the stall (as), falling past it; KL so it
     just holds level at its stall speed vs. Drag D = KL V^2 (cd0 + ki CL^2): pulling hard bleeds speed (its best
     lift-to-drag ratio ld);
   - its engine: a propeller's push no more than its power over its speed (kw, W/kg) nor tw of its weight standing; a jet's
     tw always. The pilot's hand on the throttle holds its cruise (vc), all the way open when it's slower, shut when faster;
   - the stick sets the angle of attack it asks of its wings (as a real elevator does), from what holds its path (let go:
     the autopilot's level, or its line) to the most lift (pulled) or pushed over; the wings take it over tau (slower when
     slow). Held hard at speed the path curves right round - a loop, over the top upside down (its body angle past 90). Too
     slow, the wings can't hold it and the nose drops - the stall;
   - upside down and let go, it rolls upright the way it's flying (the half loop and roll: the reversal);
   - its body (pitch, drawn) is its path less its angle of attack - the nose up in a flare, nose high at slow speed.
   Speeds in metres a second inside, world units outside (v.spd, v.vx, v.vy - as before). The game's gravity (CAR_G).
   Hooks for the weather (later - user 16:16: "I would like the weather to eventually affect the plane"): its speed is its
   speed through the air (gam, spd); the air's own movement is the place a wind or a storm's gusts will come in.
   ================================================================ */
// each kind: its stall and cruise speeds (m/s - cruise from AIR_KMH / VTUNE, so the GAME EDITOR's TOP SPEED is its cruise), engine
// (kw W/kg, tw its push standing over its weight, jet: always tw), best lift-to-drag, how fast its nose answers (tau, s), its
// stalling angle of attack (as, rad), the most its wings may pull (n: times its weight - the pilot's and the airframe's limit; a
// loop needs speed for it: the Cessna's only from a dive)
// (user Nov 3 13:08: its numbers in VTUNE - fl_<kind>, 01-z-vehicle-tune.js - so the GAME EDITOR and the Flight Lab tune them live)
// (the Spitfire, Nov 3: a little slower than the P-51, lands slower, answers quicker and pulls tighter - 29-zzz-warplanes.js)
const flRow = (k, vc, jet) => {
  const T = () => VTUNE['fl_' + k], r = { vc, jet: jet ? 1 : 0 };
  for (const p of ['vs', 'kw', 'tw', 'ld', 'tau', 'n', 'turn']) Object.defineProperty(r, p, { get: () => T()[p], enumerable: true });
  Object.defineProperty(r, 'as', { get: () => T().as * Math.PI / 180, enumerable: true });   // (kept in degrees, used in radians)
  return r;
};
const FLIGHT = {
  plane: flRow('plane', () => VTUNE.plane.kmh / 3.6),
  spitfire: flRow('spitfire', () => VTUNE.spitfire.kmh / 3.6),
  cessna: flRow('cessna', () => VTUNE.fl_cessna.kmh / 3.6),
  jet: flRow('jet', () => VTUNE.fl_jet.kmh / 3.6, true),
  seaplane: flRow('seaplane', () => VTUNE.fl_seaplane.kmh / 3.6),
};
// its numbers as the GAME EDITOR (WORLD PROPERTIES > VEHICLES > FLIGHT) and the Flight Lab show them: [key, label, max, step, unit,
// what it does] - the same rows in both; where each is kept (flKey: a warplane's cruise is its SPEED, plane.kmh / spitfire.kmh)
const FL_PROPS = [['vs', 'STALL SPEED', 120, 0.5, 'm/s', 'Slowest speed that holds level flight'], ['kmh', 'CRUISE SPEED', 1000, 5, 'km/h', 'Speed the throttle holds'],
  ['kw', 'ENGINE POWER', 3000, 10, 'W/kg', 'Propeller power per kg (0 = jet)'], ['tw', 'MAX THRUST', 2, 0.01, 'x weight', 'Static thrust, times its weight'],
  ['ld', 'GLIDE RATIO', 30, 0.5, '', 'Lift over drag: higher keeps speed in a pull'], ['tau', 'PITCH RESPONSE', 2, 0.01, 's', 'Seconds for the nose to follow the stick'],
  ['as', 'STALL ANGLE', 30, 0.25, 'deg', 'Wing angle where lift breaks away'], ['n', 'MAX G', 12, 0.1, 'g', 'Hardest pull the stick can ask'],
  ['turn', 'TURNAROUND G', 6, 0.1, 'g', 'Pull when turning round: bleeds speed']];
const FL_KINDS = [['plane', 'P-51'], ['spitfire', 'SPITFIRE'], ['cessna', 'CESSNA'], ['jet', '747'], ['seaplane', 'SEAPLANE']];
const flKey = (kind, p) => p === 'kmh' && (kind === 'plane' || kind === 'spitfire') ? [kind, 'kmh'] : ['fl_' + kind, p];
// which FLIGHT row a vehicle flies by (null: not a plane of the one flight model) - its sound, the Flight Lab
function flyKindOf(v) {
  if (!v) return null;
  if (planes.includes(v) || oldPlanes.includes(v)) return wpKind(v).flight;
  if (traffic.includes(v)) return v.kind === 'jet' ? 'jet' : 'cessna';
  if (seaplanes.includes(v)) return 'seaplane';
  return null;
}
const FLY_KI = 0.1;                       // (induced drag: CL^2 times this)
const FLY_KI_TURN = 0.02;                 // (turning round: its pull's drag - user Nov 3 14:53, "Turning should reduce the airspeed"; Nov 5
                                          // 10:40: "Planes are almost stalling just by turning, they should barely lose any speed" - 0.3 -> 0.02)
const FLY_TURN_CL = 0.9;                  // (the most of its wings' lift a turn round asks: it never stalls by turning alone, only already near its stall)
// (user Nov 5 10:40) let go with its nose just under the horizon (FLY_LEVEL_BAND, radians: ~7 degrees), upright and flying well, it
// eases level by itself - no height lost without you noticing. Further down, slow or on its back: the trim, as always
const FLY_LEVEL_BAND = 0.12;
// (user Nov 5 10:40: "Raising the nose from a dive should be easier ... Like 30% easier") pulling up while diving: the stick
// counts this much more and the nose answers this much quicker
const FLY_DIVE_PULL = 1.3;
const FLY_ROLL_T = 0.45;
// (user Nov 3 15:17: "on takeoff and landing, rather than seeing the plane maintain its horizontal angle and raising in altitude,
// there's this flip to make the head higher") its FLAPS: near the ground - just off it, climbing out, or coming in to land - its
// wings lift FLY_FLAP more (their lift coefficient, on top of their angle's) and drag a little more, as a real plane's flaps do: slow
// as it is there, it flies with its body nearly level instead of its nose high. They come out with the take-off and the approach
// and go in over FLY_FLAP_T seconds once it's away. Nothing sets its angle: off the ground its body is the angle it had on it
const FLY_FLAP = 0.2, FLY_FLAP_T = 2;
const flyWrap = a => { a = (a + Math.PI) % (2 * Math.PI); if (a < 0) a += 2 * Math.PI; return a - Math.PI; };
