    let gw = v.loiter.y == null ? 0 : clamp((v.loiter.y - v.y) / 150, -0.3, 0.3);
    gw = Math.max(gw, 0.2 * clamp((1.3 * FL.vs - Vn) / (0.3 * FL.vs), 0, 1));   // (too slow: nose down - gam is + down)
