  if (v.gam == null || !isFinite(v.gam)) { const f = v[fk] || 1; v.gam = Math.atan2(v.vy || 0, (v.vx || 0) * f || Math.max(1, v.spd || 0)); v.aoa = 0; v.bp = null; }
