    const l = ends[Math.floor(armPieceR() * ends.length)] * armPieceRnd(0.88, 1);
    const h = armPieceRnd(-22, 6);                                    // anywhere up the torn section, deck to keel
    const x = p.x + l * ca - h * sa, y = p.y + l * sa + h * ca;
