        x, y, vx: p.vx * 0.5 + armPieceRnd(-25, 25), vy: armPieceRnd(-12, 12), a: armPieceRnd(0, 6.28), w: armPieceRnd(-6, 6),
        sw: light ? armPieceRnd(1, 2.4) : armPieceRnd(1, 3), sh: armPieceRnd(0.8, 1.6),
        col: light ? LIGHT_JUNK[(armPieceR() * LIGHT_JUNK.length) | 0] : DEBRIS_COLS[(armPieceR() * DEBRIS_COLS.length) | 0],
