    for (let q = MSPL_RUN[0], q1 = MSPL_RUN[1], i = 0; q < q1; q++, i++) { const [h, r, f] = msplLobe(Q.H[q], Q.v0[q], Q.d[q], mt); if (h > 1) now.push([Q.c[q] * (1 + 0.5 * f), Q.r[q] * (0.55 + 0.45 * Math.min(1, r * 1.6)) * (1 + 0.6 * f), h, Q.l[q], f, i]); }
    const fMid = now.length ? now[now.length - 1][4] : 1;
    // the rays: thin streaks out from its foot, breaking into dashes, then dots, toward their ends
    const RY = msplRays.c;
    msplRun(msplRays, id);
    for (let q = MSPL_RUN[0], q1 = MSPL_RUN[1]; q < q1; q++) {
      const [len, , f] = msplLobe(RY.L[q], RY.v0[q], RY.d[q], mt); if (len < 2) continue;
      const ra = RY.a[q], rseed = RY.seed[q], rw = RY.w[q];
      const ux = Math.sin(ra), uy = -Math.cos(ra), bx = mx + RY.c[q], n = Math.ceil(len * SV / PB);
      for (let j = 0; j < n; j++) {
        const u = j / n, wx = bx + ux * len * u - wl * uy * len * u, wy = sy + uy * len * u;
        const hh = hash(j * 1.7 + rseed + Math.floor(mt * 10) * 0.37);
        if (hh < Math.max(0, u - 0.35) * 1.2 + f * 0.6) continue;             // (dashes, then dots, toward its end; more so as it falls)
        const X = Math.floor(PX(wx) / PB) * PB, Y = Math.floor(PY(wy) / PB) * PB;
        if (Y + PB > PY(surfaceY(wx))) continue;                              // (never under the water)
        C.fillStyle = u > 0.7 ? pal[2] : pal[0];
        C.fillRect(X, Y, PB * (rw > 1 && u < 0.5 ? 2 : 1), PB);
      }
    }
    if (!now.length) continue;
    const top = Math.max(...now.map(q => q[2]));
