// length, pushed by the sub's wash, then sinking slowly, turning over as it goes, to lie on the sand for good
const weedBits = [], WEED_KEEP = 140;
// (kick: a blast throws it up and out first)
function weedBit(p, y, len, vx, kick = 0) {
  if (SIM_ONLY || fxHidden(p.x) || len < 2) return;
  const kelp = p.kind === 'kelp';
  weedBits.push({ x: p.x, y, len, kelp, n: kelp ? 1 + (p.n > 4 ? 1 : 0) : p.n || 3, ph: (p.ph || 0) + ptR() * 6, vx: vx * ptRnd(0.25, 0.45) + ptRnd(-6, 6) + ptRnd(-1, 1) * kick * 0.6,
    vy: -ptRnd(2, 8) - kick * ptRnd(0.3, 0.7), a: (p.bend || 0) * 0.04, w: Math.sign(vx || ptRnd(-1, 1) || 1) * ptRnd(0.25, 0.6), lie: (Math.sign(vx || ptRnd(-1, 1)) || 1) * ptRnd(1.25, 1.5), rest: false, t: 0 });
  if (weedBits.length > WEED_KEEP) weedBits.shift();               // (the oldest on the bottom go first)
}
