  const cw = typeof CAVE !== 'undefined' && CAVE && CAVE.worker, cws = cw && cw.on ? ', cave swell ' + cw.got + '/' + cw.sent + ' late ' + cw.late : cw && cw.fail ? ', cave swell off: ' + cw.fail : '';
