const vehBoatMoveTo = (v, e) => { tblMoveTo(v, e); v.gate = null; v.auto = null; v.moored = false; };
defTable('ships', () => ships, { perPlayer: 2, keep: ['scorch'], make: vehShipMake, after: vehShipAfter, moveTo: vehBoatMoveTo });
