defTable('subs', () => subs, { perPlayer: 2, keep: ['scorch','parts'], make: vehSubMake, after: vehSubAfter, moveTo: vehBoatMoveTo });
defTable('oldSubs', () => oldSubs, { keep: ['scorch','parts'], make: vehSubMake, after: vehSubAfter });
