// trail it's laying - cover and splat are local: a loaded plane starts a new trail); the trails, the wisps of rushing air and
// the ice shed off its wings
defTable('planes', () => planes, { perPlayer: 2, keep: ['strand','cover','splat'], make: d => makePlane(d.id || 0) });
