// points in it) read into both
defTable('planeTrails', null, { cols: planeTrails, drawn: ['col', 'cr', 'cg', 'cb'], rows: ptFromRows, net: false });
defTable('planeTrailPts', null, { cols: planeTrailPts, drawn: ['strand', 'x', 'y', 'age', 'max', 'w', 'a'], net: false });
function ptFromRows(rows) {
  const S = { soa: 1, n: 0, top: 0, strs: [], cols: {} }, Q = { soa: 1, n: 0, top: 0, strs: [], cols: {} };
  for (const F of planeTrails.f) S.cols[F.k] = []; for (const F of planeTrailPts.f) Q.cols[F.k] = [];
  const num = v => typeof v === 'number' ? v : 0;
  rows.forEach((r, k) => {
    const id = k + 1, col = r && Array.isArray(r.col) ? r.col : null; let lp = 0;
    for (const p of (r && r.pts) || []) { Q.n++; Q.top++; lp = Q.top; for (const F of planeTrailPts.f) Q.cols[F.k].push(F.k === 'sq' ? Q.top : F.k === 'strand' ? id : num(p && p[F.k])); }
    S.n++; S.top = id;
    const v = { sq: id, pid: num(r && r.id), col: col ? 1 : 0, cr: col ? col[0] : 0, cg: col ? col[1] : 0, cb: col ? col[2] : 0, drift: r && typeof r.drift === 'number' ? r.drift : 0.12, lp };
    for (const F of planeTrails.f) S.cols[F.k].push(v[F.k]);
  });
  planeTrailPts.fromPlainCols(Q);
  return S;
}
defTable('planeWisps', () => planeWisps, { net: false, make: () => ({ x: 0, y: 0, age: 0, max: 0.5, L: 20, ux: 1, uy: 0 }) });
defTable('planeWisps', null, { cols: planeWisps, rows: rows => planeWisps.plainOfRows(rows), net: false });   // (Nov 1: a column table)
defTable('iceBits', null, { cols: iceBits, drawn: ['x', 'y', 'life', 'max', 's', 'tw'], rows: rows => iceBits.plainOfRows(rows), net: false });   // (Nov 1: a column table)
