  gl.uniform4f(u.u_p0, U.p0[0], U.p0[1], U.p0[2], U.p0[3]); gl.uniform4f(u.u_p1, U.p1[0], U.p1[1], U.p1[2], U.p1[3]); gl.uniform4f(u.u_p2, U.p2[0], U.p2[1], U.p2[2], U.p2[3]); gl.uniform1f(u.u_shade, U.shade); gl.uniform1f(u.u_nodir, U.nodir || 0); const fl = U.fl || [0, 0, 0, 0], fs = U.fls || [1, 1]; gl.uniform4f(u.u_fl, fl[0], fl[1], fl[2], fl[3]); gl.uniform2f(u.u_fls, fs[0], fs[1]); gl.uniform1i(u.u_view, U.view | 0); gl.uniform1f(u.u_body, U.body || 0); { const k = U.bk || [1.6, 0.85, 2]; gl.uniform3f(u.u_bk, k[0], k[1], k[2]); }
  gl.bindTransformFeedback(gl.TRANSFORM_FEEDBACK, GLR.ltf);
