  { let c = mix3(PAL.burn[3], PAL.burn[0], E.day); c = mix3(c, PAL.burn[1], goldK * (1 - E.overcast)); c = mix3(c, PAL.burn[2], setK); E.burn = c.map(Math.round); }
  E.w = { night: 1 - E.day, day: E.day, gold: goldK * (1 - E.overcast), set: setK, gray: grayK, storm: E.storm };
  E.palStorm = PAL.storm.map((c, t) => mix3(c.map(v => v * (0.55 + 0.45 * E.day)), E.pal[t], 0.15 + 0.45 * E.sunset).map(Math.round));
