  // the veil under each deck: the fog, and the rain's own grey curtain
  E.veil = clamp(Math.max(E.fog * 0.85, E.rain * 0.28), 0, 0.92);           // (rain alone leaves the bands behind visible)
  let sea = mix3([10, 18, 40], [52, 120, 206], E.day); sea = mix3(sea, [54, 51, 113], E.sunset * 0.9); sea = mix3(sea, [40, 62, 96], E.overcast * 0.6); sea = mix3(sea, [12, 22, 44], E.storm * 0.7);
