// The light on the sea's skin: at night the surface line catches the moonlight (brightest under the moon,
// with a glittering path of glints along the top of the water); by day the sun glints the same way.
// Wherever a hull or the pier sits on the water, its shadow keeps the line dark.
function drawSurfaceLight() {
  const nt = E.night * (1 - E.fog) * (1 - E.overcast * 0.8);
  const dy = Math.max(E.day, E.sunset * 0.9) * (1 - E.fog) * (1 - E.overcast * 0.85);
  const moonOn = moonXs[viewIdx] > -1e8 && nt > 0.05, sunOn = sunXs[viewIdx] > -1e8 && dy > 0.05;
  if (!moonOn && !sunOn) return;
  const spans = hullSpans();
  for (const b of sailboats) if (b.state === 'sail') spans.push([b.x - sailHalf(b), b.x + sailHalf(b)]);
  for (const sb of subs) if (sb.state === 'out' && sb.y < waterLv(sb.x) + 6) spans.push([sb.x - SUB_L * 0.45, sb.x + SUB_L * 0.45]);
  for (let p = 0; p < 2; p++) if (crew[p].mode === 'boat') spans.push([crew[p].x - 8, crew[p].x + 8]);
  const ns = spans.length, shaded = wx => { for (let k = 0; k < ns; k++) { const sp = spans[k]; if (wx > sp[0] - 2 && wx < sp[1] + 2) return true; } return false; };   // (the same test, no iterator a column)
  const tick = Math.floor(time * 6), lw = SV > 1.6 ? 3 : 2;
  const step = PB;
  if (moonOn) {
    const mx = moonXs[viewIdx], warm = E.moonWarm, wid = Math.max(60, VWP * 0.22);
    const line = mix3([200, 238, 255], [255, 214, 160], warm), glint = mix3([236, 252, 255], [255, 232, 190], warm);
    C.save(); C.globalCompositeOperation = 'lighter';
    for (let c = Math.floor(-SHX / step) * step - step; c < VWP + step; c += step) {
      const wx = (c + step / 2 + CAMPX) / SV;
      if (shaded(wx)) continue;
      const y = PY(surfaceY(wx)), near = Math.exp(-(((c - mx) / wid) ** 2));
      // the whole line is lit, the stretch under the moon much more
      fillRectA(C, line, nt * (0.55 + 0.45 * near), c, y, step, lw);   // (Oct 31: no colour string a column - 40-gl.js, the same bytes)
      // glints: bright dashes riding the top of the water, thicker under the moon, flickering
      const h = hash(Math.floor(wx / 3) * 1.37 + Math.floor((tick + (c & 7)) / 2) * 0.71);
      if (h < 0.08 + 0.55 * near) fillRectA(C, glint, nt * (0.5 + 0.5 * near), c, y - lw, step, lw);
    }
    C.restore();
  }
  if (sunOn) {
    const sx = sunXs[viewIdx], wid = Math.max(50, VWP * 0.16) * (1 + E.sunset);
    const glint = mix3([255, 252, 236], [255, 214, 150], E.sunset);
    C.save(); C.globalCompositeOperation = 'lighter';
    for (let c = Math.floor(-SHX / step) * step - step; c < VWP + step; c += step) {
      const near = Math.exp(-(((c - sx) / wid) ** 2));
      if (near < 0.04) continue;
      const wx = (c + step / 2 + CAMPX) / SV;
      if (shaded(wx)) continue;
      const h = hash(Math.floor(wx / 3) * 1.37 + Math.floor((tick + (c & 7)) / 2) * 0.71);
      if (h > 0.6 * near) continue;
      fillRectA(C, glint, dy * (0.35 + 0.5 * near), c, PY(surfaceY(wx)) - lw, step, lw);
    }
    C.restore();
  }
}

const FLASH_RGB = [255, 236, 180];
/* ---- a burning ship in front of her own fire and smoke (user Oct 29: "why not do a mask based on the ship in the fire
   layer, so it's cut off by that mask instead of rendering a second ship" ... "All the big ships, the battleship, the cruise
   ships, the oil tanker, Titanic etc will have a mask"). The smoke and the fire are drawn after the world (over the front
   clouds, so trails and columns rise in front of them, and untouched by the world's night and fog tint - the flames keep
   their glow). Where a ship that is burning or smouldering is on the screen, they are drawn into a layer of their own first,
   every such ship's outline (her own art, at her own pose: tilt, harbour clip, guns) is cut out of it, and what's left goes
   on the screen: the ship, drawn and tinted in the world, shows through, in front of them. With no burning ship in the view
   (most frames) they are drawn straight on the screen as before, at no cost. SHIPCUT = false: off, to compare. ---- */
