  for (const c of civShips) if (c.state === 'sail') L.push(['ship', c]);
  for (const j of jetboats) if (j.state === 'run') L.push(['boat', j]);
  for (const c of storyCars) if (c.state === 'run') L.push(['car', c]);   // (the cars at structures and placed ones - 50-story-cars.js, 50-zz-placed.js)
  if (LAND) for (const b of sailboats) if (b.state === 'sail') L.push(['yacht', b]);   // (OPEN WORLD: the yachts, user Oct 26 - their sails yours to set)
  for (const b of balloons) if (b.state === 'fly') L.push(['balloon', b]);
