    const cols = top(n), body = cols[0] || [200, 60, 50], body2 = cols.find(c => Math.hypot(c[0] - body[0], c[1] - body[1], c[2] - body[2]) > 90) || body, glass = top(g)[0] || [150, 190, 220];
    // the body's top (under the rotor) and the skids' bottom
