  const A = chArtOf(h), hw = (A ? A.W : 110) * chK(h) * 0.42, hh = (A ? A.H : 50) * chK(h) * 0.32;
  return Math.abs(x - h.x) < hw && Math.abs(y - (h.y - chSkid(h) * 0.8)) < hh;
