  // (user Oct 29, gen/open/ref/civships_overlap_containers_oct29.png: zoomed out a box a few pixels high was all edge lines -
  // light top, dark bottom - and read as stripes) its ribs, lit top and shaded bottom only once it's big enough to carry them
  if (H < 5 || W < 8) return;
  const e = Math.max(1, Math.round(Math.min(SV * 0.8, H / 6)));
  const rib = Math.max(1, Math.round(SV * 0.7)), step = Math.max(2, Math.round(W / 6));
  if (W >= 16) { tone(v => (v * 0.72) | 0); for (let k = step; k < W - 1; k += step) fillRectA(C, K, 1, X + k, Y, rib, H); }
