  if (!a) { drawContainerPx(Math.round(PX(x) - W / 2), Math.round(PY(y) - H / 2), W, H, k.col, k.dead); return; }
  C.save(); C.translate(PX(x), PY(y)); C.rotate(a); drawContainerPx(-Math.round(W / 2), -Math.round(H / 2), W, H, k.col, k.dead); C.restore();
