    const X0 = Math.round(ox + px * s), X1 = Math.round(ox + (px + CONT_PW) * s), Y0 = Math.round(oy + (CSLOT.deck - CONT_PH * (j + 1)) * s), Y1 = Math.round(oy + (CSLOT.deck - CONT_PH * j) * s);
