    for (const dx of [-4, 4]) thickLine(PX(cr.tx + dx), PY(hb - 1), PX(cr.tx + dx * 1.3), PY(cr.hy), Math.max(1, SV * 0.55));
    C.fillStyle = '#e0b030'; C.fillRect(Math.round(PX(cr.tx - CONT_W / 2 - 1)), Math.round(PY(cr.hy)), Math.round((CONT_W + 2) * SV), Math.max(1, Math.round(2.4 * SV)));
    C.fillStyle = '#7a5a14'; C.fillRect(Math.round(PX(cr.tx - CONT_W / 2 - 1)), Math.round(PY(cr.hy + 2)), Math.round((CONT_W + 2) * SV), Math.max(1, Math.round(0.9 * SV)));
    if (cr.load) drawContainerAt(cr.tx, cr.hy + 3 + CONT_H / 2, 0, cr.load);
