const HOSE_DEF = { wpress: 0.6, wflow: 1, wpow: 1, steam: 1, fflame: 1 };
const hoseP = k => { const v = NSKY.P[k]; return typeof v === 'number' ? v : HOSE_DEF[k]; };
const hoseV = () => 170 + 230 * hoseP('wpress');     // the water's speed out of the cannon
