const hoseR = sysRng('hose'), hoseRnd = (a, b) => a + hoseR() * (b - a);
defTable('hoseDrops', null, { cols: hoseDrops, drawn: ['x', 'y', 'vx', 'vy', 'age', 'br', 'sp'], rows: rows => hoseDrops.plainOfRows(rows), net: false });
