  for (const j of spaceJunk) if (j.state === 'wreck' && j.burn > 0) add(j.x - 26, j.x + 26, j.y - 20, j.y + 6, 1, pw => { j.burn -= 25 * HOSE_OUT * pw; if (j.burn <= 0) { j.burn = 0; hoseOut(j.x, j.y - 6, 1); } });
