        for (let wx = f.x - w; wx < f.x + w; wx += st / SV) {
          const near = 1 - Math.abs(wx - f.x) / w, h = fwHash(Math.floor(wx / 3) * 1.37 + Math.floor(time * 8) * 0.71);
          if (h > 0.25 + 0.6 * near) continue;
          fill(f.col.l, 0.75 * g * near); C.fillRect(sq(PX(wx)), sq(PY(surfaceY(wx))) - q, st, q);
        }
