      const P = FW_K[f.kind], t = f.t, L = f.life, fade = t < L * 0.42 ? 1 : clamp(1 - (t - L * 0.42) / (L * 0.58), 0, 1);
      const a0 = dayK * Math.min(1, t * 12) * (0.35 + 0.65 * fade);
