          if (t < 1.4 && j % 2 === 0) { fill([60, 70, 150], 0.3 * a0 * (1 - t / 1.4)); const [mx, my] = at(Math.cos(an), Math.sin(an), d, t * 0.45); for (let s = 0; s < 6; s++) dot(cx + (mx - cx) * s / 6 + (x - mx) * 0, cy + (my - cy) * s / 6); }
          const tw = 0.5 + 0.5 * Math.sin(time * (6 + 5 * fwHash(sd + j * 5)) + j), big = fwHash(sd + j * 9) < 0.35 && fade > 0.4 ? 2 : 1;
          fill(j % 3 ? Lc : M, a0 * (0.55 + 0.45 * tw));
