        if (f.kind === 'willow') d = 0.8 + 0.3 * fwHash(sd + j * 2.3) + 0.25 * Math.max(0, Math.sin(an));   // (the lower ones longer)
        if (f.kind === 'chrys') d = 0.94 + 0.08 * fwHash(sd + j * 2.3);
