        if (f.kind === 'willow' && t < 1.6) { fill([90, 96, 190], 0.18 * a0); const [ax, ay] = at(ux, uy, d, t * 0.3); for (let s = 0; s < 5; s++) dot(ax + (bx - ax) * s / 5, ay + (by - ay) * s / 5); }   // (the faint thin trail behind)
