const krCol = x => (x * SV - CAMPX - K0X) / KCS, krRow = y => (y * SV - TOPPX - K0Y) / KCS;
const krWX = c => (c * KCS + K0X + CAMPX) / SV, krWY = r => (r * KCS + K0Y + TOPPX) / SV;
function krHspan(y, x0, x1, col) { if (y < 0 || y >= KTH) return; if (x0 < 0) x0 = 0; if (x1 > KTW - 1) x1 = KTW - 1; if (x0 > x1) return; KB.fill(col, y * KTW + x0, y * KTW + x1 + 1); }
