function krSpans(r) { const k = Math.max(1, Math.round(r * 2)); let s = KR_SPANS.get(k); if (!s) { const R = k / 2, n = Math.floor(R); s = []; for (let dy = -n; dy <= n; dy++) s.push(Math.floor(Math.sqrt(Math.max(0, (R + 0.5) * (R + 0.5) - dy * dy)))); KR_SPANS.set(k, s); } return s; }
