    const s = Math.round(SUB_K * SV * 160) / 160, art = subArtOf(sb)[sb.facing], own = sb.art || art, I = scaled(own.I, s, true), wlY = Math.round(SUB_WL_ROW * s), ks = sb._krS ?? 1;
