/* ---- the desert's plants (user Oct 25: "the desert is an oasis with palm trees"; and their reference's scrub and
   cacti): palms round the oasis, dry scrub and the odd cactus across the desert, standing on the field behind the
   ground the way the forest's trees do. Pictures made once, in pixels ---- */
let desertArt = null;
function buildDesertArt() {
  const mk = (W, H, fn) => { const c = makeCanvas(W, H), x = c.getContext('2d'), id = x.createImageData(W, H); fn((px, py, col) => { px = Math.round(px); py = Math.round(py); if (px < 0 || py < 0 || px >= W || py >= H) return; const o = (py * W + px) * 4; id.data[o] = col[0]; id.data[o + 1] = col[1]; id.data[o + 2] = col[2]; id.data[o + 3] = 255; }, W, H); x.putImageData(id, 0, 0); return c; };
  const palm = seed => mk(70, 96, (put, W, H) => {
    const r = seededRng(seed), lean = (r() - 0.5) * 0.5, top = 14 + r() * 8;
    const TR = [[122, 88, 58], [96, 68, 46], [146, 108, 72]], LF = [[86, 128, 52], [62, 98, 44], [118, 156, 66], [42, 70, 36]];
    // the trunk: a curving column of rings
    let tx = W / 2, cx = 0;
    for (let y = H - 1; y > top; y--) { const u = (H - y) / (H - top); cx = W / 2 + lean * 30 * u * u; for (let k = -2; k <= 2; k++) put(cx + k, y, (y % 5 === 0) ? TR[1] : k < 0 ? TR[2] : TR[0]); tx = cx; }
    // the fronds: drooping arcs out from the crown, each a spine with leaflets
    const n = 7 + Math.floor(r() * 3);
    for (let i = 0; i < n; i++) {
      const a = -Math.PI / 2 + (i / (n - 1) - 0.5) * 2.9 + (r() - 0.5) * 0.2, L = 22 + r() * 12;
      for (let s = 0; s < L; s++) {
        const u = s / L, x = tx + Math.cos(a) * s, y = top + Math.sin(a) * s + u * u * 16;
        put(x, y, LF[3]);
        const lw = 4 * Math.sin(u * Math.PI);
        for (let q = 1; q <= lw; q++) { put(x - Math.sin(a) * q, y + Math.cos(a) * q + q * 0.6, q < lw * 0.5 ? LF[2] : LF[0]); put(x + Math.sin(a) * q * 0.6, y - Math.cos(a) * q * 0.6 + q * 0.6, LF[1]); }
      }
    }
    for (let k = -3; k <= 3; k++) for (let j = -2; j <= 2; j++) if (k * k + j * j < 8) put(tx + k, top + j + 1, k + j < 0 ? [150, 110, 60] : [110, 76, 44]);   // (the crown, its dates)
  });
  const cactus = seed => mk(26, 48, (put, W, H) => {
    const r = seededRng(seed), G = [[92, 128, 70], [70, 104, 58], [124, 158, 88], [48, 74, 44]], top = 4 + r() * 8;
    const col = (x0, y0, y1, w) => { for (let y = y0; y < y1; y++) for (let k = 0; k < w; k++) put(x0 + k, y, k === 0 ? G[2] : k === w - 1 ? G[3] : (k + y) % 3 === 0 ? G[1] : G[0]); };
    col(W / 2 - 3, top, H, 6);
    const ay = top + 10 + r() * 10, by = top + 14 + r() * 10;
    for (let k = 0; k < 6; k++) put(W / 2 - 4 - k, ay + 8, G[1]); col(W / 2 - 10, ay, ay + 9, 4);
    for (let k = 0; k < 6; k++) put(W / 2 + 3 + k, by + 6, G[1]); col(W / 2 + 7, by - 2, by + 7, 4);
  });
  const scrub = seed => mk(34, 18, (put, W, H) => {
    const r = seededRng(seed), C = [[138, 112, 70], [112, 86, 56], [166, 140, 88], [94, 104, 60]];
    for (let i = 0; i < 70; i++) { const a = -Math.PI * (0.1 + 0.8 * r()), L = 4 + r() * 12; let x = W / 2 + (r() - 0.5) * 10, y = H - 1; for (let s = 0; s < L; s++) { x += Math.cos(a); y += Math.sin(a) * 0.9; put(x, y, C[(i + s) % 4]); } }
  });
  // (user Oct 27, the Desert Art Kit - gen/open/desert.py: palms built from its ringed trunk and crowns, each its own
  // height, bend and crown; its cacti; its scrub - agave, dry bush, grass tufts, a flowering shrub, a dead branch - at
  // the game's pixel scale. The drawn ones above only if its pictures are missing)
  const DA = desertKitArt();
  desertArt = DA ? { palms: DA.palms, cacti: DA.cacti, scrub: DA.scrub, kit: true } : { palms: [1, 2, 3, 4].map(palm), cacti: [5, 6, 7].map(cactus), scrub: [8, 9, 10, 11].map(scrub) };
}
