  land.lkRocks = false;
  if (!land.lakes) return;
  const R = seededRng(6161), seaAt = x => onLand(x) && lakeAt(x);   // (every lake's bed the sea's - user Nov 3: every water as the ocean, not only a bed marked SEA; a lake's own columns, never the sea's inside its span)
  // (user Oct 28, 19:02: "yes" - the sea's big rock formations too: mesas, spires and mounds out in a SEA lake's deeper
