      const W = Math.round(wU / REEF_K), H = Math.round(hU / REEF_K) + 50, top = rockProfile(W, H - 50, kind, RR);
      let base = -Infinity; for (let c = 0; c < W; c += 4) base = Math.max(base, landTop(x - wU / 2 + c * REEF_K));
      const y0 = base + 4 - (H - 50) * REEF_K, topW = new Float32Array(W), x0r = x - wU / 2;
      for (let c = 0; c < W; c++) topW[c] = y0 + top[c] * REEF_K;
      const sp = rockLater(W, H, top, RR, 0, null, true, RK_SOLID, g => { for (let c = 0; c < W; c++) { const r = Math.ceil((landTop(x0r + c * REEF_K) + 3 - y0) / REEF_K); if (r < H) g.clearRect(c, Math.max(0, r), 1, H - r); } });   // (its foot cut away below the bed - when it's painted)
      rockForms.push({ x0: x - wU / 2, x1: x - wU / 2 + W * REEF_K, y0, sp, topW, lk: true });   // (packed when out of sight - 04-zzz-pics.js)
