            const c = Math.floor(W * (0.15 + 0.7 * R())), k2 = R(), kind = k2 < 0.45 ? 'weed' : k2 < 0.6 ? 'branch' : k2 < 0.72 ? 'fan' : k2 < 0.86 ? 'brain' : 'tube';
