const lakeEdCaves = () => ISLANDS.filter(I => !I.t && Number.isFinite(I.wl) && shpK(I) === 'H').map(I => {
  const K = LAKE_ED.cv.get(I) || {}, [a, b] = caveSpan(I), Q = shpPoly(I);
  Object.assign(K, { cave: I, x0: Q.x0, x1: Q.x1, spill: a, bot: b, deep: (Q.x0 + Q.x1) / 2, lv: I.wl }); LAKE_ED.cv.set(I, K); return K; });
const lakeEdPockets = () => (land.pockets || []).filter(K => K.bot - K.spill >= LAKE_POCKET_MIN).concat(typeof ISLANDS !== 'undefined' ? lakeEdCaves() : []);
