  cactus: { hp: 6, ign: 14, burn: 26, reach: 32, pow: 1, douse: 2, grow: 0.2 },
  scrub:  { hp: 2, ign: 1.4, burn: 8, reach: 44, pow: 2, douse: 5, grow: 1.2 },
