// wrecks, the planes' crashes, the launch pads - and their tables, at the end of this file)
const lrR = sysRng('landRest'), lrRnd = (a, b) => a + (b - a) * lrR();
const awR = sysRng('armyWrecks'), awRnd = (a, b) => a + (b - a) * awR();
const crshR = sysRng('crashes'), crshRnd = (a, b) => a + (b - a) * crshR();
