  { const W = land.waterW; land.waterW = W ? [Math.min(W[0], x0), Math.max(W[1], x1)] : [x0, x1]; }   // (the water there woken: it finds its way in the cells as they are now - 50-land-water)
  const c = landWake.c, A = c.x0, B = c.x1;
  for (let i = 0; i < landWake.n; i++) if (x1 >= A[i] - 8 && x0 <= B[i] + 8) { A[i] = Math.min(A[i], x0); B[i] = Math.max(B[i], x1); c.t[i] = 1.5; return; }
  landWakeRow(x0, x1, 1.5);
