    { const D = debris.c; for (let i = 0; i < debris.n; i++) { const x = D.x[i]; if (x < L0 || x > L1) continue; if (D.state[i] === 2 && onLand(x) && landWoke(x, 1) && !landSolid(x, D.y[i] + 1.5)) { D.state[i] = 0; D.vy[i] = 0; } } }
    restLandWake(landWake);                              // (and those filed away at rest - 36-zzzz-settled.js)
    for (const T of [earthGrains, leaves]) { const c = T.c; for (let i = 0; i < T.n; i++) { const x = c.x[i]; if (x < L0 || x > L1) continue; if (c.rest[i] && landWoke(x, 1) && !landSolid(x, c.y[i] + 1.5)) { c.rest[i] = 0; c.vy[i] = 0; c.vx[i] = 0; } } }   // (Nov 1: column tables)
