    const o = land.stones[j]; if (!o || o.gone || o.loose || !o.grey || o.dh || onApron(o.x - o.rx) || onApron(o.x + o.rx)) continue;
    if (Math.abs(o.x - x) > rad + o.rx + 8 || Math.abs(o.y - y) > rad + o.ry + 8) continue;
    const P = stonePts(stonePoly(o)); let n = 0, held = 0;
    for (let k = 0; k < P.length; k += 2) { if (P[k + 1] < o.y + o.ry * 0.25) continue; n++; if (landSolid(P[k], P[k + 1] + LT_CELL * 1.5)) held++; }
    if (n && held / n < 0.25) stoneLoosen(o);
