const ltPicsOf = cv => cv ? [cv, cv._gedgeCv, ...(cv._rimCv || [])].filter(Boolean) : [];
const ltTilePics = cv => { const P = ltPicsOf(cv), n = P.length; for (let i = 0; i < n; i++) if (P[i]._fb) P.push(P[i]._fb); return P; };
