  const link = (j, c2) => { if (c2 < 0 || c2 >= n) return -1; let b = -1, bd = FIELD_BRK; for (let k = N[c2]; k < N[c2 + 1]; k++) { const d = Math.abs(y[k] - y[j]); if (d <= bd) { bd = d; b = k; } } return b; };
  const BIG = 1e6;
