  if (!deck && g0 - h.y < 40 && ht === Infinity) landCarve(h.x, g, 9);   // (on the harbour's stone or a ship's deck, no crater)
  // (its wreck: on a ship's deck it rides her - user Oct 27, [19]; on the harbour's deck it lies there till the pier goes;
  // it burns, its smoke standing over it - landCrash)
  const w = { kind: 'heli', id: h.id, x: h.x, y: deck ? h.y + heliSkid() : Math.min(g, h.y + heliSkid()), a: h.tilt, facing: h.facing, t: 0, burn: 0, deck, onDeck: !deck && ht < Infinity };
