    if (t && !(armyWaits(t, p) && t.state === 'alive')) stepTank(t, dt);   // (a placed one waits - 50-zz-placed.js)
    if (h && !(armyWaits(h, p) && (h.state === 'fly' || h.state === 'landed'))) { stepHeli(h, dt); stepRope(h, dt); }
    // (a lost one: a few seconds before the next can come in)
