  for (let i = oldLand.length - 1; i >= 0; i--) { const v = oldLand[i]; if (v.kind === 'heli') stepHeli(v, dt); else stepTank(v, dt); if (!landGoing(v)) oldLand.splice(i, 1); }   // (the lost ones still going down)
