    flashes.addRow({ x, y: fy - 10, r: 46, life: 0, max: 0.2 });
    // the fireball: a big hot heap rolling up and forward with the plane's speed
    for (let i = 0; i < 130; i++) {
      const a = -Math.PI / 2 + rnd(-1.4, 1.4), sp = Math.pow(Math.random(), 0.55) * 170;
      spawnFlame(x + rnd(-10, 10), fy - rnd(0, 10), Math.cos(a) * sp + pl.vx * 0.25, Math.sin(a) * sp * 0.8 - rnd(30, 80), rnd(1.3, 1.6), rnd(5, 9), rnd(0.9, 1.3));
    }
