    if (gy - y < crater + 10) spikeBurst(x, Math.min(y, gy), s.from === 'bomb' ? 1.3 : s.from === 'tank' ? 1 : 0.55, groundAt(x, Math.min(y, gy)));
    kickLandDust(x, y, 18);
