  sand: { foot: [150, 118, 62], mid: [204, 172, 106], tip: [242, 226, 176], dust: 'sand' },
  grass: { foot: [60, 66, 34], mid: [118, 104, 70], tip: [200, 186, 150], dust: 'dust' },
