    for (let y = 0; y < ch; y++) for (let x = 0; x < cw; x++) { const o = ((sy + y) * W + sx + x) * 4, q = (y * cw + x) * 4; for (let k = 0; k < 4; k++) id.data[q + k] = d[o + k]; if (d[o + 3] >= 40) { r += d[o]; gg += d[o + 1]; b += d[o + 2]; m++; } }
