// the sheet and a piece's box on it, or null while it's not loaded (or where there are no pictures: the simulation worker)
function seaKitArt(i) {
  const im = typeof img !== 'undefined' ? img.seaKit : null, b = SEA_KIT[i];
  if (!b || !im || !(im.naturalWidth || im.width) || (typeof SW_IN_WORKER !== 'undefined' && SW_IN_WORKER)) return null;
  return [im, b];
}
// a puff component's frame (LEAF_W x LEAF_H) in its pieces, as the Component Editor makes a puff's (a 3 x 4 grid, one bone)
function seaKitPolys() {
  const X = [102, 67.3, 32.7, -2], Y = [-1, 12, 25, 38, 51], P = [];
  for (let i = 0; i < 3; i++) for (let j = 0; j < 4; j++) P.push({ part: 'leaf', bone: 0, face: 'F', pts: [[X[i], Y[j]], [X[i], Y[j + 1]], [X[i + 1], Y[j + 1]], [X[i + 1], Y[j]]] });
  return P;
}
