        C.save(); C.translate(-W / 2 + q.x * kx, -H + q.y * ky);
        if (!drawWheel(q.r * kx, q.r * P._m, (rl || 0) / rw * sx, (sp || 0) / rw, fc, WHEEL_OFFROAD[c.art])) { C.rotate((rl || 0) / rw * sx); C.drawImage(tint(q.c), -q.n / 2 * kx, -q.n / 2 * ky, q.n * kx, q.n * ky); }
