  const kind = new Uint8Array(NN), endW = new Float64Array(NN); kind[id(0, 0)] = 1; kind[id(M, 0)] = 2;
  let ne = 0; for (let n = 0; n < NN; n++) if (KK[n] >= K - 3) ne++;
  for (let n = 0; n < NN; n++) if (KK[n] >= K - 3) endW[n] = 1 / ne;
