    if (o.ref && f.fuel < 1) f.fuel = Math.min(1, f.fuel + dt / REFUEL_S);
    if (o.rep && (f.dmg || 0) > 0) { if (f.fixDay == null) f.fixDay = W.day + 1; else if (W.day >= f.fixDay && env.time >= STORY_WAKE_H) { f.dmg = 0; f.hits = 0; f.wings = 0; f.fixDay = null; } }
