    drawPanelBox(ug, L.q.x, L.q.y, L.q.w, L.q.h, 'rgba(18,26,42,0.96)');
    // (user Nov 3 18:52: "when you press new on a slot that has a save game, it has to say, are you sure?") the question in big
    // letters, what goes under it in red
    drawText(ug, 'ARE YOU SURE?', L.q.x + L.q.w / 2, L.q.y + 8, '#ffffff', 2, 'center');
    drawText(ug, 'SLOT ' + (SSL.confirm + 1) + "'S SAVED STORY WILL BE LOST", L.q.x + L.q.w / 2, L.q.y + 28, '#ff9a7a', 1, 'center');
    modeButton(...L.q.yes, 'YES', true); modeButton(...L.q.no, 'NO', false);
