  // (as the sky's rows: the default in brackets beside a changed one - tap it to go back)
  const show = () => { const on = VTUNE[f][k] !== d; inp.value = VTUNE[f][k]; out.textContent = fmt(VTUNE[f][k]); dv.textContent = on ? '(' + fmt(d) + ')' : ''; dv.classList.toggle('on', on); };
