  traffic: (a, b) => { drawTraffic(a, b); drawTraffic(a, b, 'air'); }, seaplanes: (a, b) => { drawSeaplanes(a, b); drawSeaplanes(a, b, 'air'); },
  balloons: (a, b) => { drawBalloons(a, b); drawBalloons(a, b, 'air'); }, blimps: (a, b) => drawBlimps(a, b),
