      Object.assign(E, H.E); GLR.on = false; viewIdx = 0; for (const Q of LOOK_LISTS()) Q[0] = [];
      const e = { v, k: civClass(v), army: false }, B = vehBox(e), pad = 0.15 * (B[1] - B[0]);
      const x0 = B[0] - pad, x1 = B[1] + pad, y0 = B[2] - pad, y1 = B[3] + pad, k = Math.min(4, 280 / (x1 - x0), 170 / (y1 - y0));
