  ARROW.forEach((row, j) => { for (let i = 0; i < 7; i++) if (row[i] === '#') { ug.fillStyle = i > 3 ? cols[1] : j < 3 && i === 2 ? cols[2] : cols[0]; ug.fillRect(Math.round(x0 + i * bw), Math.round(y0 + j * bh), Math.ceil(bw), Math.ceil(bh)); } });
  ug.globalAlpha = 1;
