// world -> the controls' layer (and the page's pixels, for presses), as the camera has it this frame
function storyToUI() {
  const a = screenToWorld(0, 0), b = screenToWorld(1000, 1000), sx = 1000 / (b[0] - a[0]), sy = 1000 / (b[1] - a[1]);
  return (x, y) => { const cx = (x - a[0]) * sx, cy = (y - a[1]) * sy, [X, Y] = toUI(cx, cy); return { cx, cy, X, Y }; };
}
const ARROW_B = 3, ARROW_GAP = 4, ARROW_BOB = 7;
const storyBuyHint = () => { const d = (SLOTS[0] || {}).dev || 'kb'; return d === 'touch' ? 'TAP TO PURCHASE' : /pad/.test(d) ? 'PRESS A TO PURCHASE' : 'PRESS SPACE TO PURCHASE'; };
// where each arrow is on the page this frame (for presses): its point (cx, cy) and how far up its arrow and label reach (up), in
// the page's pixels
