  const byL = ids.slice().sort((p, q) => lum(p) - lum(q)), K = Math.min(BP_COLS, ids.length), C = [];
  for (let k = 0; k < K; k++) { const i = byL[Math.floor((k + 0.5) * byL.length / K)]; C.push([rgb[i * 3], rgb[i * 3 + 1], rgb[i * 3 + 2]]); }
