  const [x0, y0, x1, y1] = F.box, w = x1 - x0, h = y1 - y0, k = makeCanvas(w, h);
  k.getContext('2d').drawImage(c, x0, y0 + up, w, h, 0, 0, w, h);
  c.getContext('2d').clearRect(x0, y0 + up, w, h);
