  const on = wk === 'cook' ? !!story.cook : wk === 'lamp' ? !!story.light : wk === 'beam' ? (() => { const tw = stLighthouse(), C = tw && lhCtl(tw); return !(C && C.off); })() : false;
  return { f: 0, off: false, n: -1, on };
