  o.type = 'sine'; o.frequency.setValueAtTime(64, t); o.frequency.exponentialRampToValueAtTime(23, t + 1.7);
  envGain(og, t, 1, 0.045, 1.8); o.connect(og); og.connect(w); o.onended = () => { o.disconnect(); og.disconnect(); }; o.start(t); o.stop(t + 1.9);
  noiseShot(w, t, 1.9, 'lowpass', 380, 55, 0.9, 0.8, 0.04);                            // (the silt pushed out)
  thump(w, t + 0.34, 48, 24, 0.9, 0.4);                                                  // (settling)
  noiseShot(w, t + 0.2, 3.2, 'lowpass', 160, 35, 1, 0.45, 0.6);                          // (the rumble going away)
  krBloops(w, t + 0.3, 10, 1.8, 0.05);
